// Stack Sans Headline, embedded as base64 so the certificate renderer has no
// runtime filesystem dependency — this code runs in a Cloudflare Worker, where
// there is nothing to read from. Same approach as LOGO_B64 in ./cert-pdf.ts,
// kept in its own module only because two full TTFs would otherwise bury that
// file's actual layout code under ~200K characters of base64.
//
// Source: `landing page design resources/stack-sans-headline-fonts/static/`.
// Regenerate with: base64 -i <file.ttf>
//
// Consumed via doc.embedFont(bytes, { subset: true }) — pdf-lib writes only the
// glyphs each certificate actually uses, rather than ~156KB of full font per PDF.

export const STACK_SANS_BOLD_B64 =
  ''

export const STACK_SANS_REGULAR_B64 =
  ''
